insert into public.learn_units(code, course_id, title, sort_order, status) values ('math-m1-linear-eq', (select id from public.learn_courses where code = 'math-m1-algebra'), '일차방정식', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l1', (select id from public.learn_units where code = 'math-m1-linear-eq'), '식의 값 구하기', '문자에 수를 넣는 것을 **대입**이라고 해요. 대입해서 계산한 결과가 **식의 값**이에요. 음수를 넣을 때는 괄호를 써서 실수를 줄여요.', '$x=3$일 때 $2x+1$ 은 $2\times3+1=7$ 이에요.', 0, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l1'), (select id from public.learn_skills where code = 'm.expr') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l2', (select id from public.learn_units where code = 'math-m1-linear-eq'), '등식의 성질', '등식은 **저울**과 같아요. 양변에 같은 수를 더하거나 빼고, 곱하거나(0이 아닌 수로) 나누어도 저울은 평형을 유지해요.', '$x+5=9$ 의 양변에서 $5$를 빼면 $x=4$ 예요.', 1, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l2'), (select id from public.learn_skills where code = 'm.prop') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l3', (select id from public.learn_units where code = 'math-m1-linear-eq'), '일차방정식 풀기', '$x$가 있는 항은 한쪽, 숫자는 반대쪽으로 **이항**해서 모아요. 이항하면 부호가 바뀌어요. 마지막으로 $x$ 앞의 수로 나누면 끝!', '$2x+1=9 \Rightarrow 2x=8 \Rightarrow x=4$', 2, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l3'), (select id from public.learn_skills where code = 'm.solve') on conflict do nothing;
insert into public.learn_lessons(code, unit_id, title, concept, example, sort_order, status) values ('math-l4', (select id from public.learn_units where code = 'math-m1-linear-eq'), '방정식으로 문제 풀기', '문장제는 **구하려는 것을 $x$로 놓고** → 문장을 식으로 옮기고 → 풀고 → 답이 조건에 맞는지 확인하는 순서로 풀어요.', '어떤 수의 $3$배에 $2$를 더하면 $14$ → $3x+2=14$ → $x=4$', 3, 'PUBLISHED') on conflict (code) do nothing;
insert into public.learn_lesson_skills(lesson_id, skill_id) select (select id from public.learn_lessons where code = 'math-l4'), (select id from public.learn_skills where code = 'm.word') on conflict do nothing;
